ran Strike om hulp. De detective ontdekt een verband met een manuscript waarin bekenden van de auteur zich onaangenaam herkennen. De zaak krijgt een ernstiger karakter wanneer Quine dood wordt gevonden. Samen met Robin probeert Strike de belangen en vijandigheden rond de tekst te doorgronden, voordat de dader opnieuw kan handelen. De Londense literaire wereld vormt het decor van hun tweede onderzoek.","source_type":"official_catalog","source_name":"Bureau ISBN","source_url":"https://metadata.isbn.nl/179705/zijderups.html","provenance":"original_source_reviewed_summary"}},{"relation":"editions","ref":"edition:9789022566459","key":{"isbn_13":"9789022566459"},"before":null,"after":{"work_id":975100038,"title":"Het teken van Athena","isbn_13":"9789022566459","isbn_10":"9022566455","language":"nld","publisher":"Uitgeverij Unieboek | Het Spectrum","id":975200108}},{"relation":"catalog_edition_metadata","ref":"metadata:9789022566459","key":{"edition_id":"@edition:9789022566459"},"before":null,"after":{"review_status":"approved","reviewed_at":"2026-11-01T00:00:00+01:00","review_batch":"nl-cohort003-02-20261101","evidence":[{"url":"https://metadata.isbn.nl/2083422/het-teken-van-athena.html","checkedAt":"2026-11-01","fact":"Exact edition/title/author/ISBN/format/cover source, not title-based language inference"},{"url":"https://www.lannoo.com/nl-be/young-adult/het-teken-van-athena-9789022566459","checkedAt":"2026-11-01","fact":"Exact-edition language decision"},{"url":"https://metadata.isbn.nl/ie_fcache/0000610008_Het_teken_van_Athena_0_0.jpg","checkedAt":"2026-10-31T23:12:16.974Z","sha256":"9ecc0687b8645701b5bd4ead6af973b7dd43a564d162aebe63d2cb3835d3c0cb","bytes":495665,"fact":"Manual title/author/exact edition cover binding, readable published front"}],"edition_id":"@edition:9789022566459","work_id":975100038,"bound_author_id":969300015,"bound_title":"Het teken van Athena","bound_language":"nld","bound_isbn13":"9789022566459","format":"paperback","cover_url":"https://metadata.isbn.nl/ie_fcache/0000610008_Het_teken_van_Athena_0_0.jpg","card_cover_url":null,"evidence_url":"https://metadata.isbn.nl/2083422/het-teken-van-athena.html"}},{"relation":"catalog_work_descriptions","ref":"description:1389:nl","key":{"work_id":975100038,"language":"nl"},"before":null,"after":{"review_status":"approved","reviewed_at":"2026-11-01T00:00:00+01:00","review_batch":"nl-cohort003-02-20261101","evidence":[{"url":"https://metadata.isbn.nl/2083422/het-teken-van-athena.html","checkedAt":"2026-11-01","fact":"Exact edition/title/author/ISBN/format/cover source, not title-based language inference"},{"url":"https://www.lannoo.com/nl-be/young-adult/het-teken-van-athena-9789022566459","checkedAt":"2026-11-01","fact":"Exact-edition language decision"},{"url":"https://metadata.isbn.nl/ie_fcache/0000610008_Het_teken_van_Athena_0_0.jpg","checkedAt":"2026-10-31T23:12:16.974Z","sha256":"9ecc0687b8645701b5bd4ead6af973b7dd43a564d162aebe63d2cb3835d3c0cb","bytes":495665,"fact":"Manual title/author/exact edition cover binding, readable published front"}],"work_id":975100038,"language":"nl","bound_author_id":969300015,"text":"Annabeth staat voor een opdracht die nauw verbonden is met haar moeder Athena. Tegelijk proberen Griekse en Romeinse halfgoden samen te werken, hoewel hun wederzijdse wantrouwen dat voortdurend bemoeilijkt. Percy en zijn reisgenoten moeten een groter gevaar het hoofd bieden. In het derde Helden van Olympus-boek krijgt Annabeths eigen zoektocht een centrale plaats binnen een onderneming waarvoor de groep elkaar nodig heeft.","source_type":"official_catalog","source_name":"Bureau ISBN","source_url":"https://metadata.isbn.nl/2083422/het-teken-van-athena.html","provenance":"original_source_reviewed_summary"}},{"relation":"editions","ref":"edition:9789000342426","key":{"isbn_13":"9789000342426"},"before":null,"after":{"work_id":975100039,"title":"Het huis van Hades","isbn_13":"9789000342426","isbn_10":"9000342422","language":"nld","publisher":"Uitgeverij Unieboek | Het Spectrum","id":975200109}},{"relation":"catalog_edition_metadata","ref":"metadata:9789000342426","key":{"edition_id":"@edition:9789000342426"},"before":null,"after":{"review_status":"approved","reviewed_at":"2026-11-01T00:00:00+01:00","review_batch":"nl-cohort003-02-20261101","evidence":[{"url":"https://metadata.isbn.nl/2094506/het-huis-van-hades.html","checkedAt":"2026-11-01","fact":"Exact edition/title/author/ISBN/format/cover source, not title-based language inference"},{"url":"https://www.bibliotheek.nl/catalogus/titel.429370679.html/het-huis-van-hades/","checkedAt":"2026-11-01","fact":"Exact-edition language decision"},{"url":"https://metadata.isbn.nl/ie_fcache/0000610014_Het_huis_van_Hades_0_0.jpg","checkedAt":"2026-10-31T23:12:18.996Z","sha256":"6070d4a84185e181a4eb87c6faa57bb8a89d821d91de5ac893f069167920ebb7","bytes":616364,"fact":"Manual title/author/exact edition cover binding, readable published front"}],"edition_id":"@edition:9789000342426","work_id":975100039,"bound_author_id":969300015,"bound_title":"Het huis van Hades","bound_language":"nld","bound_isbn13":"9789000342426","format":"paperback","cover_url":"https://metadata.isbn.nl/ie_fcache/0000610014_Het_huis_van_Hades_0_0.jpg","card_cover_url":null,"evidence_url":"https://metadata.isbn.nl/2094506/het-huis-van-hades.html"}},{"relation":"catalog_work_descriptions","ref":"description:1406:nl","key":{"work_id":975100039,"language":"nl"},"before":null,"after":{"review_status":"approved","reviewed_at":"2026-11-01T00:00:00+01:00","review_batch":"nl-cohort003-02-20261101","evidence":[{"url":"https://metadata.isbn.nl/2094506/het-huis-van-hades.html","checkedAt":"2026-11-01","fact":"Exact edition/title/author/ISBN/format/cover source, not title-based language inference"},{"url":"https://www.bibliotheek.nl/catalogus/titel.429370679.html/het-huis-van-hades/","checkedAt":"2026-11-01","fact":"Exact-edition language decision"},{"url":"https://metadata.isbn.nl/ie_fcache/0000610014_Het_huis_van_Hades_0_0.jpg","checkedAt":"2026-10-31T23:12:18.996Z","sha256":"6070d4a84185e181a4eb87c6faa57bb8a89d821d91de5ac893f069167920ebb7","bytes":616364,"fact":"Manual title/author/exact edition cover binding, readable published front"}],"work_id":975100039,"language":"nl","bound_author_id":969300015,"text":"Percy en Annabeth zijn van hun vrienden gescheiden en bevinden zich in Tartarus. Voor de andere halfgoden gaat de tocht verder, terwijl beide groepen een manier zoeken om de Deuren des Doods te bereiken. Hun opdrachten blijken met elkaar verbonden. Het vierde Helden van Olympus-boek volgt een strijd waarin afstand, onderling vertrouwen en de dreiging van Gaia de mogelijkheden van de reizigers bepalen.","source_type":"official_catalog","source_name":"Bureau ISBN","source_url":"https://metadata.isbn.nl/2094506/het-huis-van-hades.html","provenance":"original_source_reviewed_summary"}}]'::jsonb;receipt jsonb;r jsonb;p jsonb;k jsonb;expected jsonb;prior jsonb;ids jsonb:='{}';kv record;i integer:=0;n integer;begin
 receipt:=nullif(current_setting('lumiscore.catalog_release_receipt',true),'')::jsonb;
 if receipt->>'project' is distinct from 'hlvujbrmfdlrfxdjwsmb' or receipt->>'batch' is distinct from 'nl079-test-nl-cohort003-02-20261101' or jsonb_typeof(receipt->'rows') is distinct from 'array' or jsonb_array_length(receipt->'rows')<>60 then raise exception 'Exact manifest receipt required';end if;
 for p in select value from jsonb_array_elements(reviewed) loop
  i:=i+1;select count(*) into n from jsonb_array_elements(receipt->'rows')x where x->>'seq'=i::text;
  if n<>1 then raise exception 'Receipt manifest sequence mismatch';end if;
  select x into r from jsonb_array_elements(receipt->'rows')x where x->>'seq'=i::text;
  if r->>'relation' is distinct from p->>'relation' then raise exception 'Receipt manifest relation mismatch';end if;
  k:=p->'key';expected:=p->'after';prior:=p->'before';
  for kv in select * from jsonb_each(expected) loop
   if jsonb_typeof(kv.value)='string' and left(kv.value#>>'{}',1)='@' then
    if not ids ? substring(kv.value#>>'{}',2) then raise exception 'Receipt manifest missing parent';end if;
    expected:=jsonb_set(expected,array[kv.key],ids->substring(kv.value#>>'{}',2));end if;
  end loop;
  for kv in select * from jsonb_each(k) loop
   if jsonb_typeof(kv.value)='string' and left(kv.value#>>'{}',1)='@' then k:=jsonb_set(k,array[kv.key],ids->substring(kv.value#>>'{}',2));end if;
  end loop;
  if prior<>'null'::jsonb then execute format('select to_jsonb(jsonb_populate_record(null::public.%I,$1))',p->>'relation') into prior using prior;end if;
  execute format('select coalesce(jsonb_object_agg(x.key,x.value),''{}''::jsonb) from jsonb_each(to_jsonb(jsonb_populate_record(null::public.%I,$1))) x where $1 ? x.key',p->>'relation') into expected using expected;
  if r->'key' is distinct from k or r->'before_row' is distinct from prior or jsonb_typeof(r->'after_row') is distinct from 'object' or not coalesce((r->'after_row')@>expected,false) then raise exception 'Receipt differs from exact reviewed manifest';end if;
  if r->'after_row' ? 'id' then ids:=jsonb_set(ids,array[p->>'ref'],r->'after_row'->'id');end if;
 end loop;
end;$manifest_guard$;
do $undo$ declare receipt jsonb;r jsonb;actual jsonb;dep record;n bigint;cols text;begin
 receipt:=nullif(current_setting('lumiscore.catalog_release_receipt',true),'')::jsonb;
 if receipt->>'project' is distinct from 'hlvujbrmfdlrfxdjwsmb' or receipt->>'batch' is distinct from 'nl079-test-nl-cohort003-02-20261101' or jsonb_typeof(receipt->'rows') is distinct from 'array' or jsonb_array_length(receipt->'rows')<>60 then raise exception 'Exact first committed receipt required';end if;
 for r in select value from jsonb_array_elements(receipt->'rows') order by (value->>'seq')::integer desc loop
  if r->>'relation' not in ('authors','works','editions','catalog_work_descriptions','catalog_edition_metadata') then raise exception 'Unreviewed receipt relation';end if;
  execute format('select to_jsonb(t) from public.%I t where to_jsonb(t) @> $1 for update',r->>'relation') into actual using r->'key';
  if actual is null and r->'before_row'='null'::jsonb then continue;end if;
  if actual is not distinct from r->'before_row' then continue;end if;
  if actual is distinct from r->'after_row' then raise exception 'Later legitimate change; recovery refused';end if;
  if r->'before_row'='null'::jsonb then
   for dep in select ns.nspname,c.relname,string_agg(format('(to_jsonb(child)->%L)=($1->%L)',ca.attname,pa.attname),' and ' order by k.ord) predicate
    from pg_constraint f join pg_class c on c.oid=f.conrelid join pg_namespace ns on ns.oid=c.relnamespace
    cross join lateral unnest(f.conkey,f.confkey) with ordinality k(childkey,parentkey,ord)
    join pg_attribute ca on ca.attrelid=f.conrelid and ca.attnum=k.childkey join pg_attribute pa on pa.attrelid=f.confrelid and pa.attnum=k.parentkey
    where f.contype='f' and f.confrelid=to_regclass('public.'||(r->>'relation')) group by f.oid,ns.nspname,c.relname
   loop
    execute format('select count(*) from %I.%I child where %s',dep.nspname,dep.relname,dep.predicate) into n using r->'after_row';
    if n>0 then raise exception 'Later dependency in %.%; recovery refused',dep.nspname,dep.relname;end if;
   end loop;
   execute format('delete from public.%I t where to_jsonb(t) @> $1',r->>'relation') using r->'key';
  else
   select string_agg(format('%I=(jsonb_populate_record(null::public.%I,$1)).%I',key,r->>'relation',key),',') into cols from jsonb_each(r->'before_row') where value is distinct from r->'after_row'->key;
   execute format('update public.%I t set %s where to_jsonb(t) @> $2',r->>'relation',cols) using r->'before_row',r->'key';
  end if;
 end loop;
end;$undo$;commit;
